-- 024_fix_personal_status_cybercrime_family_courts.sql
-- إصلاح جذرى: 3 قوانين كانت مخزَّنة بالكامل كـ"مادة 1" واحدة (نفس عيب migrations/017-019)
-- بدل تقسيمها مادة مادة. يعالج السبب الجذرى: إعادة تحليل النص الكامل (المحفوظ
-- بالفعل فى body) وتقسيمه مادة مادة، مع حذف السجل الوهمى القديم لكل قانون.
--
-- 1) قانون 1/2000 (تنظيم أوضاع وإجراءات التقاضى فى مسائل الأحوال الشخصية):
--    79 مادة موضوعية مرقّمة أرقاماً (1-79، صفر فجوات، صفر تكرار) + 6 مواد إصدار
--    بالكلمات (الأولى-السادسة) استُبعدت عمداً من جدول articles اتساقاً مع اصطلاح
--    migrations/021/023 (لا تكرار فى الترقيم يستلزم suffix_order=-1 لعدم وجود تصادم رقمى).
--    فُحصت يدوياً: المادة 1 (تعريف حساب المدد) والمادة 79 (عقوبة بنك ناصر الاجتماعى
--    - صندوق تأمين النفقة المرتبط قانونياً بمنازعات الأحوال الشخصية) سليمتان.
--
-- 2) قانون 175/2018 (مكافحة جرائم تقنية المعلومات): 45 مادة (1-45، صفر فجوات) —
--    لا مواد إصدار منفصلة لهذا القانون (يبدأ مباشرة بالمادة 1 بعد الديباجة).
--    العدد يطابق تماماً ملاحظة "45 مادة" كانت مسجَّلة داخل بيانات وصفية سابقة للنص.
--    فُحصت يدوياً: المادة 1 (تعريفات) والمادة 45 (نشر القانون) سليمتان.
--
-- 3) قانون 10/2004 (إنشاء محاكم الأسرة): 15 مادة موضوعية (1-15) + 5 مواد إصدار
--    بالكلمات (الأولى-الخامسة) استُبعدت عمداً بنفس الاصطلاح. فُحصت يدوياً بالكامل —
--    نص قصير وسليم تماماً، لا أخطاء نصية ولا فجوات.
--
-- ملاحظة: قانون 164/2025 (إيجار جديد) استُبعد عمداً من هذا الملف — نصه المصدر تالف
-- بتلف حروف/كلمات داخل متن المواد نفسها (ليس فقط فى العناوين)، فتقسيمه الآن غير
-- آمن. يحتاج مصدر نص أنظف أولاً (نُقل لقائمة "المسار ب" فى التقرير الرئيسى).

BEGIN;

-- ===== ps1_2000: قانون تنظيم بعض أوضاع وإجراءات التقاضى فى مسائل الأحوال الشخصية 1/2000 (79 مادة) =====

DO $dops1_2000$
DECLARE
  v_law_id uuid;
  v_article_count int;
BEGIN
  SELECT id INTO v_law_id FROM laws WHERE law_no = 1 AND law_year = 2000;
  IF v_law_id IS NULL THEN
    RAISE NOTICE 'law 1/2000 not found, skipping fix';
    RETURN;
  END IF;
  SELECT count(*) INTO v_article_count FROM articles WHERE law_id = v_law_id;
  IF v_article_count = 1 THEN
    DELETE FROM articles WHERE law_id = v_law_id AND article_no = 1 AND article_suffix_order = 0;
    RAISE NOTICE 'law 1/2000: removed legacy single-blob article row';
  ELSE
    RAISE NOTICE 'law 1/2000: already has % articles, skipping delete (already fixed or unexpected state)', v_article_count;
  END IF;
END
$dops1_2000$;

WITH ins_ps1_2000_1_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 1, 0, NULL, NULL, $ps1_2000_1$تحسب المدد والمواعيد الإجرائية المنصوص عليها في هذا القانون بالتقويم الميلادي.$ps1_2000_1$
  FROM laws WHERE law_no = 1 AND law_year = 2000
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $ps1_2000_1$تحسب المدد والمواعيد الإجرائية المنصوص عليها في هذا القانون بالتقويم الميلادي.$ps1_2000_1$, '2020-09-05', 'active' FROM ins_ps1_2000_1_0;

WITH ins_ps1_2000_2_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 2, 0, NULL, NULL, $ps1_2000_2$تثبت أهلية التقاضي في مسائل الأحوال الشخصية للولاية على النفس لمن أتم خمس عشرة سنة ميلادية كاملة متمتعا بقواه العقلية.
وينوب عن عديم الأهلية أو ناقصها ممثله القانوني، فإذا لم يكن له من يمثله أو كان هناك وجه لمباشرة إجراءات التقاضي بالمخالفة لرأي ممثله أو في مواجهته عينت المحكمة له وصى خصومة من تلقاء نفسها أو بناء على طلب النيابة العامة أو الغير.$ps1_2000_2$
  FROM laws WHERE law_no = 1 AND law_year = 2000
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $ps1_2000_2$تثبت أهلية التقاضي في مسائل الأحوال الشخصية للولاية على النفس لمن أتم خمس عشرة سنة ميلادية كاملة متمتعا بقواه العقلية.
وينوب عن عديم الأهلية أو ناقصها ممثله القانوني، فإذا لم يكن له من يمثله أو كان هناك وجه لمباشرة إجراءات التقاضي بالمخالفة لرأي ممثله أو في مواجهته عينت المحكمة له وصى خصومة من تلقاء نفسها أو بناء على طلب النيابة العامة أو الغير.$ps1_2000_2$, '2020-09-05', 'active' FROM ins_ps1_2000_2_0;

WITH ins_ps1_2000_3_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 3, 0, NULL, NULL, $ps1_2000_3$لا يلزم توقيع محام على صحف دعاوى الأحوال الشخصية أمام المحكمة الجزئية، فإذا رفعت الدعوى بغير توقيع محام على صحيفتها كان للمحكمة عند الضرورة أن تندب محاميا للدفاع عن المدعى. ويحدد الحكم الصادر في الدعوى أتعابا للمحامي المنتدب، تتحملها الخزانة العامة، وذلك دون إخلال بالتزام مجالس النقابات الفرعية بتقديم المساعدات القضائية على النحو المنصوص عليه في القانون رقم 17 لسنة 1983 بشأن إصدار قانون المحاماة.
وتعفي دعاوى النفقات وما في حكمها من الأجور والمصروفات بجميع أنواعها من كافة الرسوم القضائية في كل مراحل التقاضي.$ps1_2000_3$
  FROM laws WHERE law_no = 1 AND law_year = 2000
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $ps1_2000_3$لا يلزم توقيع محام على صحف دعاوى الأحوال الشخصية أمام المحكمة الجزئية، فإذا رفعت الدعوى بغير توقيع محام على صحيفتها كان للمحكمة عند الضرورة أن تندب محاميا للدفاع عن المدعى. ويحدد الحكم الصادر في الدعوى أتعابا للمحامي المنتدب، تتحملها الخزانة العامة، وذلك دون إخلال بالتزام مجالس النقابات الفرعية بتقديم المساعدات القضائية على النحو المنصوص عليه في القانون رقم 17 لسنة 1983 بشأن إصدار قانون المحاماة.
وتعفي دعاوى النفقات وما في حكمها من الأجور والمصروفات بجميع أنواعها من كافة الرسوم القضائية في كل مراحل التقاضي.$ps1_2000_3$, '2020-09-05', 'active' FROM ins_ps1_2000_3_0;

WITH ins_ps1_2000_4_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 4, 0, NULL, NULL, $ps1_2000_4$يكون للمحكمة – في إطار تهيئة الدعوى للحكم – تبصرة الخصوم في مواجهتهم بما يتطلبه حسن سير الدعوى، ومنحهم أجلا لتقديم دفاعهم.
ولها أن تندب إخصائيا اجتماعيا أو أكثر لتقديم تقرير عن الحالة المعروضة عليها أو عن مسألة فيها، وتحدد أجلا لتقديم التقرير لا يزيد على أسبوعين.
ويتم الندب من قوائم الإخصائيين الاجتماعيين التي يصدر بها قرار من وزير العدل بناءً على ترشيح وزير التأمينات والشئون الاجتماعية.$ps1_2000_4$
  FROM laws WHERE law_no = 1 AND law_year = 2000
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $ps1_2000_4$يكون للمحكمة – في إطار تهيئة الدعوى للحكم – تبصرة الخصوم في مواجهتهم بما يتطلبه حسن سير الدعوى، ومنحهم أجلا لتقديم دفاعهم.
ولها أن تندب إخصائيا اجتماعيا أو أكثر لتقديم تقرير عن الحالة المعروضة عليها أو عن مسألة فيها، وتحدد أجلا لتقديم التقرير لا يزيد على أسبوعين.
ويتم الندب من قوائم الإخصائيين الاجتماعيين التي يصدر بها قرار من وزير العدل بناءً على ترشيح وزير التأمينات والشئون الاجتماعية.$ps1_2000_4$, '2020-09-05', 'active' FROM ins_ps1_2000_4_0;

WITH ins_ps1_2000_5_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 5, 0, NULL, NULL, $ps1_2000_5$للمحكمة أن تقرر نظر المسائل المتعلقة بالأحوال الشخصية – مراعاة لاعتبارات النظام العام أو الآداب – في غرفة المشورة وبحضور أحد أعضاء النيابة العامة متى كانت ممثلة في الدعوى، وتنطق بالأحكام والقرارات في جلسة علنية.$ps1_2000_5$
  FROM laws WHERE law_no = 1 AND law_year = 2000
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id
