WITH ins_ps1_2000_6_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 6, 0, NULL, NULL, $ps1_2000_6$مع عدم الإخلال باختصاص النيابة العامة برفع الدعوى في مسائل الأحوال الشخصية على وجه الحسبة المنصوص عليه في القانون رقم 3 لسنة 1996، للنيابة العامة رفع الدعوى ابتداء في مسائل الأحوال الشخصية إذا تعلق الأمر بالنظام العام أو الآداب، كما يجوز لها أن تتدخل في دعاوى الأحوال الشخصية التي تختص بها المحاكم الجزئية.
وعلى النيابة العامة أن تتدخل في دعاوى الأحوال الشخصية والوقف التي تختص بها المحاكم الابتدائية أو محاكم الاستئناف وإلا كان الحكم باطلا.$ps1_2000_6$
  FROM laws WHERE law_no = 1 AND law_year = 2000
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $ps1_2000_6$مع عدم الإخلال باختصاص النيابة العامة برفع الدعوى في مسائل الأحوال الشخصية على وجه الحسبة المنصوص عليه في القانون رقم 3 لسنة 1996، للنيابة العامة رفع الدعوى ابتداء في مسائل الأحوال الشخصية إذا تعلق الأمر بالنظام العام أو الآداب، كما يجوز لها أن تتدخل في دعاوى الأحوال الشخصية التي تختص بها المحاكم الجزئية.
وعلى النيابة العامة أن تتدخل في دعاوى الأحوال الشخصية والوقف التي تختص بها المحاكم الابتدائية أو محاكم الاستئناف وإلا كان الحكم باطلا.$ps1_2000_6$, '2020-09-05', 'active' FROM ins_ps1_2000_6_0;

WITH ins_ps1_2000_7_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 7, 0, NULL, NULL, $ps1_2000_7$لا تقبل عند الإنكار دعوى الإقرار بالنسب أو الشهادة على الإقرار به بعد وفاة المورث إلا إذا وجدت أوراق رسمية أو مكتوبة جميعها بخط المتوفي وعليها إمضاؤه أو أدلة قطعية جازمة تدل على صحة هذا الادعاء.$ps1_2000_7$
  FROM laws WHERE law_no = 1 AND law_year = 2000
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $ps1_2000_7$لا تقبل عند الإنكار دعوى الإقرار بالنسب أو الشهادة على الإقرار به بعد وفاة المورث إلا إذا وجدت أوراق رسمية أو مكتوبة جميعها بخط المتوفي وعليها إمضاؤه أو أدلة قطعية جازمة تدل على صحة هذا الادعاء.$ps1_2000_7$, '2020-09-05', 'active' FROM ins_ps1_2000_7_0;

WITH ins_ps1_2000_8_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 8, 0, NULL, NULL, $ps1_2000_8$لا تقبل دعوى الوقف أو شروطه أو الإقرار به أو الاستحقاق فيه أو التصرفات الواردة عليه ما لم يكن الوقف ثابتا بإشهاد مشهر وفقا لأحكام القانون.
ولا تقبل دعوى الوقف أو الإرث عند الإنكار متى رفعت بعد مضى ثلاث وثلاثين سنة من وقت ثبوت الحق، إلا إذا قام عذر حال دون ذلك.
وإذا حكم بعزل ناظر الوقف أو ضم ناظر آخر إليه، تعين المحكمة في الحالتين بحكم واجب النفاذ ناظراً بصفة مؤقتة إلى أن يفصل في الدعوى بحكم نهائي.$ps1_2000_8$
  FROM laws WHERE law_no = 1 AND law_year = 2000
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $ps1_2000_8$لا تقبل دعوى الوقف أو شروطه أو الإقرار به أو الاستحقاق فيه أو التصرفات الواردة عليه ما لم يكن الوقف ثابتا بإشهاد مشهر وفقا لأحكام القانون.
ولا تقبل دعوى الوقف أو الإرث عند الإنكار متى رفعت بعد مضى ثلاث وثلاثين سنة من وقت ثبوت الحق، إلا إذا قام عذر حال دون ذلك.
وإذا حكم بعزل ناظر الوقف أو ضم ناظر آخر إليه، تعين المحكمة في الحالتين بحكم واجب النفاذ ناظراً بصفة مؤقتة إلى أن يفصل في الدعوى بحكم نهائي.$ps1_2000_8$, '2020-09-05', 'active' FROM ins_ps1_2000_8_0;

WITH ins_ps1_2000_9_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 9, 0, NULL, NULL, $ps1_2000_9$تختص المحكمة الجزئية بنظر المسائل الواردة بهذه المادة.
وبمراعاة أحكام المادة (52) من هذا القانون، يكون حكمها في الدعاوى قابلا للطعن بالاستئناف ما لم ينص القانون على نهائيته، وذلك كله على الوجه التالي:
أولاً – المسائل المتعلقة بالولاية على النفس:
1 – الدعاوى المتعلقة بحضانة الصغير وحفظه ورؤيته وضمه والانتقال به.
2 – الدعاوى المتعلقة بالنفقات وما في حكمها من الأجور والمصروفات بجميع أنواعها.
3 – الدعاوى المتعلقة بالإذن للزوجة بمباشرة حقوقها، متى كان القانون الواجب التطبيق يقضى بضرورة الحصول على إذن الزوج لمباشرة تلك الحقوق.
4 – دعاوى المهر والجهاز والدوطة والشبكة وما في حكمها.
ويكون الحكم نهائيا إذا كان المطلوب لا يتجاوز النصاب الانتهائى للقاضي الجزئي.
5 – تصحيح القيود المتعلقة بالأحوال الشخصية في وثائق الزواج والطلاق.
6 – توثيق ما يتفق عليه ذوو الشأن أمام المحكمة فيما يجوز شرعا.
7 – الإذن بزواج من لا ولى له.
8 – تحقيق الوفاة والوراثة والوصية الواجبة، ما لم يثر بشأنها نزاع.
9- دعاوى الحبس لامتناع المحكوم عليه عن تنفيذ أحكام النفقات وما في حكمها ويكون الحكم في ذلك نهائياً
ثانياً – المسائل المتعلقة بالولاية على المال متى كان مال المطلوب حمايته لا تتجاوز قيمته نصاب اختصاص المحكمة الجزئية:
1 – تثبيت الوصي المختار وتعيين الوصي والمشرف والمدير ومراقبة أعمالهم والفصل في حساباتهم وعزلهم واستبدالهم.
2- إثبات الغيبة وإنهاؤها وتعيين الوكيل عن الغائب ومراقبة أعماله وعزله واستبداله.
3 – تقرير المساعدة القضائية ورفعها وتعيين المساعد القضائي واستبداله.
4 – استمرار الولاية أو الوصاية إلى ما بعد سن الحادية والعشرين والإذن للقاصر بتسلم أمواله لإدارتها وفقا لأحكام القانون والإذن له بمزاولة التجارة وإجراء التصرفات التي يلزم للقيام بها الحصول على إذن، وسلب أي من هذه الحقوق أو وقفها أو الحد منها.
5 – تعيين مأذون بالخصومة عن القاصر أو الغائب ولو لم يكن له مال.
6 – تقدير نفقة للقاصر من ماله والفصل فيما يقوم من نزاع بين ولى النفس أو ولى التربية وبين الوصي فيما يتعلق بالإنفاق على القاصر أو تربيته أو العناية به.
7 – إعفاء الولي في الحالات التي يجوز إعفاؤه فيها وفقا لأحكام قانون الولاية على المال.
8 – طلب تنحى الولي عن ولايته واستردادها.
9 – الإذن بما يصرف لزواج القاصر في الأحوال التي يوجب القانون استئذان المحكمة فيها.
10 – جميع المواد الأخرى المتعلقة بإدارة الأموال وفقا لأحكام القانون واتخاذ الإجراءات التحفظية والمؤقتة الخاصة بها مهما كانت قيمة المال.
11 – تعيين مصف للتركة وعزله واستبداله والفصل في المنازعات المتعلقة بالتصفية متى كانت قيمة التركة لا تزيد على نصاب اختصاص المحكمة الجزئية.$ps1_2000_9$
  FROM laws WHERE law_no = 1 AND law_year = 2000
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $ps1_2000_9$تختص المحكمة الجزئية بنظر المسائل الواردة بهذه المادة.
وبمراعاة أحكام المادة (52) من هذا القانون، يكون حكمها في الدعاوى قابلا للطعن بالاستئناف ما لم ينص القانون على نهائيته، وذلك كله على الوجه التالي:
أولاً – المسائل المتعلقة بالولاية على النفس:
1 – الدعاوى المتعلقة بحضانة الصغير وحفظه ورؤيته وضمه والانتقال به.
2 – الدعاوى المتعلقة بالنفقات وما في حكمها من الأجور والمصروفات بجميع أنواعها.
3 – الدعاوى المتعلقة بالإذن للزوجة بمباشرة حقوقها، متى كان القانون الواجب التطبيق يقضى بضرورة الحصول على إذن الزوج لمباشرة تلك الحقوق.
4 – دعاوى المهر والجهاز والدوطة والشبكة وما في حكمها.
ويكون الحكم نهائيا إذا كان المطلوب لا يتجاوز النصاب الانتهائى للقاضي الجزئي.
5 – تصحيح القيود المتعلقة بالأحوال الشخصية في وثائق الزواج والطلاق.
6 – توثيق ما يتفق عليه ذوو الشأن أمام المحكمة فيما يجوز شرعا.
7 – الإذن بزواج من لا ولى له.
8 – تحقيق الوفاة والوراثة والوصية الواجبة، ما لم يثر بشأنها نزاع.
9- دعاوى الحبس لامتناع المحكوم عليه عن تنفيذ أحكام النفقات وما في حكمها ويكون الحكم في ذلك نهائياً
ثانياً – المسائل المتعلقة بالولاية على المال متى كان مال المطلوب حمايته لا تتجاوز قيمته نصاب اختصاص المحكمة الجزئية:
1 – تثبيت الوصي المختار وتعيين الوصي والمشرف والمدير ومراقبة أعمالهم والفصل في حساباتهم وعزلهم واستبدالهم.
2- إثبات الغيبة وإنهاؤها وتعيين الوكيل عن الغائب ومراقبة أعماله وعزله واستبداله.
3 – تقرير المساعدة القضائية ورفعها وتعيين المساعد القضائي واستبداله.
4 – استمرار الولاية أو الوصاية إلى ما بعد سن الحادية والعشرين والإذن للقاصر بتسلم أمواله لإدارتها وفقا لأحكام القانون والإذن له بمزاولة التجارة وإجراء التصرفات التي يلزم للقيام بها الحصول على إذن، وسلب أي من هذه الحقوق أو وقفها أو الحد منها.
5 – تعيين مأذون بالخصومة عن القاصر أو الغائب ولو لم يكن له مال.
6 – تقدير نفقة للقاصر من ماله والفصل فيما يقوم من نزاع بين ولى النفس أو ولى التربية وبين الوصي فيما يتعلق بالإنفاق على القاصر أو تربيته أو العناية به.
7 – إعفاء الولي في الحالات التي يجوز إعفاؤه فيها وفقا لأحكام قانون الولاية على المال.
8 – طلب تنحى الولي عن ولايته واستردادها.
9 – الإذن بما يصرف لزواج القاصر في الأحوال التي يوجب القانون استئذان المحكمة فيها.
10 – جميع المواد الأخرى المتعلقة بإدارة الأموال وفقا لأحكام القانون واتخاذ الإجراءات التحفظية والمؤقتة الخاصة بها مهما كانت قيمة المال.
11 – تعيين مصف للتركة وعزله واستبداله والفصل في المنازعات المتعلقة بالتصفية متى كانت قيمة التركة لا تزيد على نصاب اختصاص المحكمة الجزئية.$ps1_2000_9$, '2020-09-05', 'active' FROM ins_ps1_2000_9_0;

WITH ins_ps1_2000_10_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 10, 0, NULL, NULL, $ps1_2000_10$تختص المحكمة الابتدائية بنظر دعاوى الأحوال الشخصية التي لا تدخل في اختصاص المحكمة الجزئية، ودعاوى الوقف وشروطه والاستحقاق فيه والتصرفات الواردة عليه.
ويكون للمحكمة الابتدائية المختصة محليا بنظر دعوى الطلاق أو التطليق أو التفريق الجسماني دون غيرها، الحكم ابتدائيا في دعاوى النفقات أو الأجور وما في حكمها سواء للزوجة أو الأولاد أو الأقارب، وحضانة الصغير وحفظه ورؤيته وضمه والانتقال به ومسكن حضانته.
وتلتزم المحاكم الابتدائية والجزئية التي رفعت أو ترفع أمامها دعوى بأي من هذه الطلبات بإحالتها إلى تلك المحكمة حتى يصدر فيها حكم قطعي واحد.
وللمحكمة أثناء سير الدعوى أن تصدر أحكاما مؤقتة واجبة النفاذ بشأن الرؤية أو بتقرير نفقة وقتية أو تعديل ما عساها تكون قد قررته من نفقة بالزيادة أو النقصان.
ولا يجوز الطعن على تلك الأحكام المؤقتة التي تصدر أثناء سير هذه الدعاوى إلا بصدور الحكم النهائي فيها.$ps1_2000_10$
  FROM laws WHERE law_no = 1 AND law_year = 2000
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id
)
