WITH ins_ps1_2000_11_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 11, 0, NULL, NULL, $ps1_2000_11$تختص المحكمة الابتدائية التي يجرى في دائرتها توثيق عقد زواج الأجانب بالحكم في الاعتراض على هذا الزواج أو طلب الحجر على أحد طرفي العقد إذا كان القانون واجب التطبيق يجعل الحجر سببا لزوال أهليته للزواج، ويترتب على إقامة الدعوى وقف إتمام الزواج حتى يفصل نهائيا فيها.
كما تختص المحكمة الابتدائية بتوقيع الحجر ورفعه وتعيين القيم ومراقبة أعماله والفصل في حساباته وعزله واستبداله، والإذن للمحجور عليه بتسلم أمواله لإدارتها، وفقا لأحكام القانون وسلب هذا الحق أو الحد منه، وتعيين مأذون بالخصومة عنه، وتقدير نفقة للمحجور عليه في ماله، والفصل فيما يقوم من نزاع بين ولى النفس وولى التربية ويبين القيم فيما يتعلق بالإنفاق على المحجور عليه.$ps1_2000_11$
  FROM laws WHERE law_no = 1 AND law_year = 2000
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id
)
