SELECT id, 1, $ps1_2000_11$تختص المحكمة الابتدائية التي يجرى في دائرتها توثيق عقد زواج الأجانب بالحكم في الاعتراض على هذا الزواج أو طلب الحجر على أحد طرفي العقد إذا كان القانون واجب التطبيق يجعل الحجر سببا لزوال أهليته للزواج، ويترتب على إقامة الدعوى وقف إتمام الزواج حتى يفصل نهائيا فيها.
كما تختص المحكمة الابتدائية بتوقيع الحجر ورفعه وتعيين القيم ومراقبة أعماله والفصل في حساباته وعزله واستبداله، والإذن للمحجور عليه بتسلم أمواله لإدارتها، وفقا لأحكام القانون وسلب هذا الحق أو الحد منه، وتعيين مأذون بالخصومة عنه، وتقدير نفقة للمحجور عليه في ماله، والفصل فيما يقوم من نزاع بين ولى النفس وولى التربية ويبين القيم فيما يتعلق بالإنفاق على المحجور عليه.$ps1_2000_11$, '2020-09-05', 'active' FROM ins_ps1_2000_11_0;

WITH ins_ps1_2000_12_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 12, 0, NULL, NULL, $ps1_2000_12$إذا قضت المحكمة بسلب الولاية أو وقفها عهدت بها إلى من يلي من سلبت ولايته أو أوقفت وفقا للقانون الواجب التطبيق ثم إلى من يليه بالتتابع، فإن امتنع من عهد إليه بها بعد إخطاره على النحو المنصوص عليه في المادة (40) من هذا القانون أو لم تتوافر فيه أسباب الصلاحية، فعلى المحكمة أن تعهد بالولاية لأي شخص أمين أو لإحدى المؤسسات الاجتماعية.
وتسلم الأموال في هذه الحالة للنائب المعين بوصفه مديرا مؤقتا، وذلك بعد جردها على النحو الوارد بالمادة (41) من هذا القانون.
وتتخذ النيابة العامة على وجه السرعة الإجراءات اللازمة لتعيين وصى على المشمول بالولاية.$ps1_2000_12$
  FROM laws WHERE law_no = 1 AND law_year = 2000
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id
)
