1 – تختص المحكمة التي يقع في دائرتها موطن المدعى أو المدعى عليه بنظر الدعوى المرفوعة من الأولاد أو الزوجة أو الوالدين أو الحاضنة حسب الأحوال، في المواد الآتية:
