WITH ins_ps1_2000_17_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 17, 0, NULL, NULL, $ps1_2000_17$لا تقبل الدعاوى الناشئة عن عقد الزواج إذا كانت سن الزوجة تقل عن ست عشرة سنة ميلادية، أو كانت سن الزوج تقل عن ثماني عشرة سنة ميلادية وقت رفع الدعوى.
ولا تقبل عند الإنكار الدعاوى الناشئة عن عقد الزواج – في الوقائع اللاحقة على أول أغسطس سنة 1931 – ما لم يكن الزواج ثابت بوثيقة رسمية، ومع ذلك تقبل دعوى التطليق أو الفسخ بحسب الأحوال دون غيرهما إذا كان الزواج ثابتا بأية كتابة.
ولا تقبل دعوى الطلاق بين الزوجين متحدي الطائفة والملة إلا إذا كانت شريعتهما تجيزه.$ps1_2000_17$
  FROM laws WHERE law_no = 1 AND law_year = 2000
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $ps1_2000_17$لا تقبل الدعاوى الناشئة عن عقد الزواج إذا كانت سن الزوجة تقل عن ست عشرة سنة ميلادية، أو كانت سن الزوج تقل عن ثماني عشرة سنة ميلادية وقت رفع الدعوى.
