WITH ins_ps1_2000_18_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 18, 0, NULL, NULL, $ps1_2000_18$تلتزم المحكمة في دعاوى الولاية على النفس بعرض الصلح على الخصوم، ويعد من تخلف عن حضور جلسة الصلح – مع علمه بها – بغير عذر مقبول رافضا له.
وفي دعاوى الطلاق والتطليق لا يحكم بهما إلا بعد أن تبذل المحكمة جهدا في محاولة الصلح بين الزوجين وتعجز عن ذلك، فإن كان للزوجين ولد تلتزم المحكمة بعرض الصلح مرتين على الأقل تفصل بينهما مدة لا تقل عن ثلاثين يوما ولا تزيد على ستين يوما.$ps1_2000_18$
  FROM laws WHERE law_no = 1 AND law_year = 2000
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $ps1_2000_18$تلتزم المحكمة في دعاوى الولاية على النفس بعرض الصلح على الخصوم، ويعد من تخلف عن حضور جلسة الصلح – مع علمه بها – بغير عذر مقبول رافضا له.
وفي دعاوى الطلاق والتطليق لا يحكم بهما إلا بعد أن تبذل المحكمة جهدا في محاولة الصلح بين الزوجين وتعجز عن ذلك، فإن كان للزوجين ولد تلتزم المحكمة بعرض الصلح مرتين على الأقل تفصل بينهما مدة لا تقل عن ثلاثين يوما ولا تزيد على ستين يوما.$ps1_2000_18$, '2020-09-05', 'active' FROM ins_ps1_2000_18_0;

WITH ins_ps1_2000_19_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 19, 0, NULL, NULL, $ps1_2000_19$في دعاوى التطليق التي يوجب فيها القانون ندب حكمين يجب على المحكمة أن تكلف كلا من الزوجين بتسمية حكم من أهله – قدر الإمكان – في الجلسة التالية على الأكثر، فإن تقاعس أيهما عن تعيين حكمه أو تخلف عن حضور هذه الجلسة عينت المحكمة حكما عنه.
وعلى الحكمين المثول أمام المحكمة في الجلسة التالية لتعيينهما ليقررا ما خلصا إليه معا، فإن اختلف أو تخلف أيهما عن الحضور تسمع المحكمة أقوالهما أو أقوال الحاضر منهما بعد حلف اليمين.
وللمحكمة أن تأخذ بما انتهى إليه الحكمان أو بأقوال أيهما، أو بغير ذلك مما تستقيه من أوراق الدعوى.$ps1_2000_19$
  FROM laws WHERE law_no = 1 AND law_year = 2000
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $ps1_2000_19$في دعاوى التطليق التي يوجب فيها القانون ندب حكمين يجب على المحكمة أن تكلف كلا من الزوجين بتسمية حكم من أهله – قدر الإمكان – في الجلسة التالية على الأكثر، فإن تقاعس أيهما عن تعيين حكمه أو تخلف عن حضور هذه الجلسة عينت المحكمة حكما عنه.
وعلى الحكمين المثول أمام المحكمة في الجلسة التالية لتعيينهما ليقررا ما خلصا إليه معا، فإن اختلف أو تخلف أيهما عن الحضور تسمع المحكمة أقوالهما أو أقوال الحاضر منهما بعد حلف اليمين.
