WITH ins_ps1_2000_20_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 20, 0, NULL, NULL, $ps1_2000_20$للزوجين أن يتراضيا فيما بينهما على الخلع، فإن لم يتراضيا عليه وأقامت الزوجة دعواها بطلبه وافتدت نفسها وخالعت زوجها بالتنازل عن جميع حقوقها المالية الشرعية وردت عليه الصداق الذي أعطاه لها، حكمت المحكمة بتطليقها عليه.
ولا تحكم المحكمة بالتطليق للخلع إلا بعد محاولة الصلح بين الزوجين، وندبها لحكمين لموالاة مساعي الصلح بينهما، خلال مدة لا تجاوز ثلاثة أشهر، وعلى الوجه المبين بالفقرة الثانية من المادة (18) والفقرتين الأولى والثانية من المادة (19) من هذا القانون، ويعد أن تقرر الزوجة صراحة أنها تبغض الحياة مع زوجها وأنه لا سبيل لاستمرار الحياة الزوجية بينهما وتخشى ألا تقيم حدود الله بسبب هذا البغض.
ولا يصح أن يكون مقابل الخلع إسقاط حضانة الصغار، أو نفقتهم أو أي حق من حقوقهم.
ويقع بالخلع في جميع الأحوال طلاق بائن.
ويكون الحكم – في جميع الأحوال – غير قابل للطعن عليه بأي طريق من طرق الطعن.$ps1_2000_20$
  FROM laws WHERE law_no = 1 AND law_year = 2000
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $ps1_2000_20$للزوجين أن يتراضيا فيما بينهما على الخلع، فإن لم يتراضيا عليه وأقامت الزوجة دعواها بطلبه وافتدت نفسها وخالعت زوجها بالتنازل عن جميع حقوقها المالية الشرعية وردت عليه الصداق الذي أعطاه لها، حكمت المحكمة بتطليقها عليه.
