WITH ins_ps1_2000_22_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 22, 0, NULL, NULL, $ps1_2000_22$مع عدم الإخلال بحق الزوجة في إثبات مراجعة مطلقها لها بكافة طرق الإثبات، لا يقبل عند الإنكار ادعاء الزوج مراجعته مطلقته ما لم يعلنها بهذه المراجعة بورقة رسمية قبل انقضاء ستين يوماً لمن تحيض وتسعين يوماً لمن عدتها بالأشهر من تاريخ توثيق طلاقه لها، وذلك ما لم تكن حاملاً أو تقر بعدم انقضاء عدتها حتى إعلانها بالمراجعة.$ps1_2000_22$
