SELECT id, 1, $ps1_2000_22$مع عدم الإخلال بحق الزوجة في إثبات مراجعة مطلقها لها بكافة طرق الإثبات، لا يقبل عند الإنكار ادعاء الزوج مراجعته مطلقته ما لم يعلنها بهذه المراجعة بورقة رسمية قبل انقضاء ستين يوماً لمن تحيض وتسعين يوماً لمن عدتها بالأشهر من تاريخ توثيق طلاقه لها، وذلك ما لم تكن حاملاً أو تقر بعدم انقضاء عدتها حتى إعلانها بالمراجعة.$ps1_2000_22$, '2020-09-05', 'active' FROM ins_ps1_2000_22_0;

WITH ins_ps1_2000_23_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 23, 0, NULL, NULL, $ps1_2000_23$إذا كان دخل المطلوب الحكم عليه بنفقة أو ما في حكمها محل منازعة جدية، ولم يكن في أوراق الدعوى ما يكفي لتحديده، وجب على المحكمة أن تطلب من النيابة العامة إجراء التحقيق الذي يمكنها من بلوغ هذا التحديد.
وتباشر النيابة العامة بنفسها إجراء التحقيق في هذا الشأن.
ومع عدم الإخلال بأحكام قرار رئيس الجمهورية بالقانون رقم 205 لسنة 1990 في شأن سرية الحسابات بالبنوك، تلتزم أية جهة حكومية أو غير حكومية بإفادة النيابة العامة بما تحت يدها من معلومات، تكون منتجة في تحديد دخل المطلوب منه النفقة.
ولا يجوز استخدام ما تسفر عنه هذه التحقيقات من معلومات في غير المادة التي أجريت بشأنها.
ويجب على النيابة العامة أن تنهى التحقيق وترسله مشفوعاً بمذكرة موجزة بالنتائج التي خلصت إليها في موعد لا يجاوز ثلاثين يوماً من تاريخ وصول طلب المحكمة إليها.$ps1_2000_23$
  FROM laws WHERE law_no = 1 AND law_year = 2000
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $ps1_2000_23$إذا كان دخل المطلوب الحكم عليه بنفقة أو ما في حكمها محل منازعة جدية، ولم يكن في أوراق الدعوى ما يكفي لتحديده، وجب على المحكمة أن تطلب من النيابة العامة إجراء التحقيق الذي يمكنها من بلوغ هذا التحديد.
وتباشر النيابة العامة بنفسها إجراء التحقيق في هذا الشأن.
