WITH ins_ps1_2000_24_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 24, 0, NULL, NULL, $ps1_2000_24$على طالب إشهاد الوفاة أو الوراثة أو الوصية الواجبة أن يقدم طلباً بذلك إلى المحكمة المختصة مرفقاً به ورقة رسمية تثبت الوفاة وإلا كان الطلب غير مقبول.
ويجب أن يشتمل الطلب على بيان آخر موطن للمتوفي وأسماء الورثة والموصي لهم وصية واجبة وموطنهم إن وجدوا، وعلى الطالب أن يعلنهم بالحضور أمام المحكمة في الميعاد المحدد لنظر الطلب، ويحقق القاضي الطلب بشهادة من يوثق به وله أن يضيف إليها التحريات الإدارية حسبما يراه، فإذا ما أنكر أحد الورثة أو الموصي لهم وصية واجبة ورأي القاضي أن الإنكار جدي، كان عليه أن يحيل الطلب إلى المحكمة الابتدائية المختصة للفصل فيه.$ps1_2000_24$
  FROM laws WHERE law_no = 1 AND law_year = 2000
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $ps1_2000_24$على طالب إشهاد الوفاة أو الوراثة أو الوصية الواجبة أن يقدم طلباً بذلك إلى المحكمة المختصة مرفقاً به ورقة رسمية تثبت الوفاة وإلا كان الطلب غير مقبول.
