WITH ins_ps1_2000_26_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 26, 0, NULL, NULL, $ps1_2000_26$تتولى النيابة العامة رعاية مصالح عديمي الأهلية وناقصيها والغائبين والتحفظ على أموالهم والإشراف على إدارتها وفقاً لأحكام هذا القانون.
ولها أن تندب – فيما ترى اتخاذه من تدابير – أحد مأموري الضبط القضائي.
كما يكون لها أن تستعين بمعاونين يلحقون بها بقرار يصدره وزير العدل، ويعتبر هؤلاء المعاونون من مأموري الضبط القضائي في خصوص الأعمال التي تناط بهم أثناء تأديتهم لوظيفتهم.
وللنيابة العامة أن تقدر نفقة وقتية من أموال مستحق النفقة إلى حين الحكم بتقديرها.$ps1_2000_26$
  FROM laws WHERE law_no = 1 AND law_year = 2000
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
