WITH ins_ps1_2000_27_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 27, 0, NULL, NULL, $ps1_2000_27$على الأقارب الذين كانوا يقيمون مع المتوفي في معيشة واحدة أو أكبر الراشدين من الورثة إبلاغ النيابة العامة بواقعة وفاة شخص غائب أو عديم أهلية أو ناقصها أو حمل مستكن، أو وفاة الولي أو الوصي أو القيم أو الوكيل عن الغائب خلال ثلاثة أيام من تاريخ حصول الوفاة.
وعلى الأقارب إبلاغ النيابة العامة خلال ذات المدة عن فقد أهلية أو غياب أحد أفراد الأسرة إذا كان مقيما معهم في معيشة واحدة.$ps1_2000_27$
  FROM laws WHERE law_no = 1 AND law_year = 2000
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id
)
