WITH ins_ps1_2000_28_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 28, 0, NULL, NULL, $ps1_2000_28$على الأطباء المعالجين ومديري المستشفيات والمصحات على حسب الأحوال إبلاغ النيابة العامة عن حالات فقد الأهلية الناشئة عن عاهة عقلية بمجرد ثبوت ذلك لديهم.
