WITH ins_ps1_2000_30_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 30, 0, NULL, NULL, $ps1_2000_30$يعاقب على مخالفة أحكام المواد (27، 28، 29) من هذا القانون بغرامة لا تقل عن خمسين جنيها ولا تجاوز مائة جنيه، فإذا كان عدم التبليغ بقصد الإضرار بعديم الأهلية أو ناقصها أو الغائب أو غيرهم من ذوي الشأن تكون العقوبة الحبس مدة لا تزيد على سنة وبغرامة لا تقل عن مائة جنيه ولا تجاوز ألف جنيه أو بإحدى هاتين العقوبتين.$ps1_2000_30$
