WITH ins_ps1_2000_32_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 32, 0, NULL, NULL, $ps1_2000_32$تقيد النيابة العامة طلبات الحجر والمساعدة القضائية واستمرار الولاية أو الوصاية وسلب الولاية أو الحد منها أو وقفها وسلب الإذن للقاصر أو المحجور عليه أو الحد منه وإثبات الغيبة والحد من سلطة الوكيل عن الغائب ومنع المطلوب الحجر عليه أو سلب ولايته من التصرف أو تقييد حريته فيه، وذلك يوم وساعة تقديم الطلب في سجل خاص.
ويقوم القيد في السجل مقام التسجيل، وينتج أثره من تاريخ إجرائه متى قضى بإجابة الطلب. وعلى النيابة العامة شطب القيد إذا قضى نهائيا برفض الطلب.
ويصدر وزير العدل قرارا بإجراءات القيد والشطب.$ps1_2000_32$
  FROM laws WHERE law_no = 1 AND law_year = 2000
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $ps1_2000_32$تقيد النيابة العامة طلبات الحجر والمساعدة القضائية واستمرار الولاية أو الوصاية وسلب الولاية أو الحد منها أو وقفها وسلب الإذن للقاصر أو المحجور عليه أو الحد منه وإثبات الغيبة والحد من سلطة الوكيل عن الغائب ومنع المطلوب الحجر عليه أو سلب ولايته من التصرف أو تقييد حريته فيه، وذلك يوم وساعة تقديم الطلب في سجل خاص.
ويقوم القيد في السجل مقام التسجيل، وينتج أثره من تاريخ إجرائه متى قضى بإجابة الطلب. وعلى النيابة العامة شطب القيد إذا قضى نهائيا برفض الطلب.
ويصدر وزير العدل قرارا بإجراءات القيد والشطب.$ps1_2000_32$, '2020-09-05', 'active' FROM ins_ps1_2000_32_0;

WITH ins_ps1_2000_33_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 33, 0, NULL, NULL, $ps1_2000_33$على النيابة العامة بمجرد ورود التبليغ إليها وفقا لأحكام هذا القانون أن تتخذ الإجراءات اللازمة للمحافظة على حقوق الحمل المستكن أو عديم الأهلية أو ناقصها أو الغائب وأن تحصر مؤقتا ما لهم من أموال ثابتة أو منقولة أو حقوق وما عليهم من التزامات في محضر يوقع عليه ذوو الشأن.
وللنيابة العامة أن تتخذ الإجراءات الوقتية أو التحفظية اللازمة للمحافظة على هذه الأموال وأن تأمر بوضع الأختام عليها، ولها بناء على أمر صادر من قاضى الأمور الوقتية أن تنقل النقود والأوراق المالية والمستندات والمصوغات وغيرها مما يخشى عليه إلى خزانة أحد المصارف أو إلى مكان أمين.
وللنيابة العامة – عند الاقتضاء – أن تأذن لوصى التركة أو منفذ الوصية أو مديرها إن وجد أو لأي شخص أمين آخر بالصرف على جنازة المتوفي والإنفاق على من تلزمه نفقتهم وإدارة الأعمال التي يخشى عليها من فوات الوقت.
وللنيابة العامة أن تعدل عن أي قرار اتخذته تطبيقاً لأحكام هذه المادة.$ps1_2000_33$
  FROM laws WHERE law_no = 1 AND law_year = 2000
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $ps1_2000_33$على النيابة العامة بمجرد ورود التبليغ إليها وفقا لأحكام هذا القانون أن تتخذ الإجراءات اللازمة للمحافظة على حقوق الحمل المستكن أو عديم الأهلية أو ناقصها أو الغائب وأن تحصر مؤقتا ما لهم من أموال ثابتة أو منقولة أو حقوق وما عليهم من التزامات في محضر يوقع عليه ذوو الشأن.
وللنيابة العامة أن تتخذ الإجراءات الوقتية أو التحفظية اللازمة للمحافظة على هذه الأموال وأن تأمر بوضع الأختام عليها، ولها بناء على أمر صادر من قاضى الأمور الوقتية أن تنقل النقود والأوراق المالية والمستندات والمصوغات وغيرها مما يخشى عليه إلى خزانة أحد المصارف أو إلى مكان أمين.
وللنيابة العامة – عند الاقتضاء – أن تأذن لوصى التركة أو منفذ الوصية أو مديرها إن وجد أو لأي شخص أمين آخر بالصرف على جنازة المتوفي والإنفاق على من تلزمه نفقتهم وإدارة الأعمال التي يخشى عليها من فوات الوقت.
وللنيابة العامة أن تعدل عن أي قرار اتخذته تطبيقاً لأحكام هذه المادة.$ps1_2000_33$, '2020-09-05', 'active' FROM ins_ps1_2000_33_0;

WITH ins_ps1_2000_34_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 34, 0, NULL, NULL, $ps1_2000_34$للنيابة العامة بناء على إذن مسبب من القاضي الجزئي دخول المساكن والأماكن اللازم دخولها لاتخاذ الإجراءات التحفظية المنصوص عليها في هذا القانون. ولها أن تندب لذلك – بأمر مسبب يحدد فيه المسكن أو المكان – أحد مأموري الضبط القضائي.$ps1_2000_34$
