WITH ins_ps1_2000_35_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 35, 0, NULL, NULL, $ps1_2000_35$لا يلزم اتباع الإجراءات المنصوص عليها في المادتين السابقتين إذا لم يتجاوز مال المطلوب حمايته ثلاثة آلاف جنيه، تتعدد بتعددهم، وفي هذه الحالة تسلم النيابة العامة المال إلى من يقوم على شئونه ما لم تر النيابة العامة اتباع الإجراءات المشار إليها بالضوابط والأوضاع المقررة بهاتين المادتين.$ps1_2000_35$
