SELECT id, 1, $ps1_2000_35$لا يلزم اتباع الإجراءات المنصوص عليها في المادتين السابقتين إذا لم يتجاوز مال المطلوب حمايته ثلاثة آلاف جنيه، تتعدد بتعددهم، وفي هذه الحالة تسلم النيابة العامة المال إلى من يقوم على شئونه ما لم تر النيابة العامة اتباع الإجراءات المشار إليها بالضوابط والأوضاع المقررة بهاتين المادتين.$ps1_2000_35$, '2020-09-05', 'active' FROM ins_ps1_2000_35_0;

WITH ins_ps1_2000_36_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 36, 0, NULL, NULL, $ps1_2000_36$يرفع الطلب إلى المحكمة المختصة من النيابة العامة أو ذوي الشأن. وفي الحالة الأخيرة يجب أن يشتمل الطلب المرفوع على البيانات التي يتطلبها قانون المرافعات في صحيفة الدعوى وأن يرفق به المستندات المؤيدة له، وعلى المحكمة أن تحيله إلى النيابة العامة لإبداء ملاحظاتها عليه كتابة خلال ميعاد تحدده لذلك. وتقوم النيابة العامة – فيما لا تختص بإصدار أمر فيه – بتحديد جلسة أمام المحكمة لنظر الطلب مشفوعا بما أجرته من تحقيقات وما انتهت إليه من رأي، وإعلان من لم ينبه عليه أمامها من ذوي الشأن بالجلسة. وللمحكمة أن تندب النيابة العامة لمباشرة أي إجراء من إجراءات التحقيق الذي تأمر به.$ps1_2000_36$
  FROM laws WHERE law_no = 1 AND law_year = 2000
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $ps1_2000_36$يرفع الطلب إلى المحكمة المختصة من النيابة العامة أو ذوي الشأن. وفي الحالة الأخيرة يجب أن يشتمل الطلب المرفوع على البيانات التي يتطلبها قانون المرافعات في صحيفة الدعوى وأن يرفق به المستندات المؤيدة له، وعلى المحكمة أن تحيله إلى النيابة العامة لإبداء ملاحظاتها عليه كتابة خلال ميعاد تحدده لذلك. وتقوم النيابة العامة – فيما لا تختص بإصدار أمر فيه – بتحديد جلسة أمام المحكمة لنظر الطلب مشفوعا بما أجرته من تحقيقات وما انتهت إليه من رأي، وإعلان من لم ينبه عليه أمامها من ذوي الشأن بالجلسة. وللمحكمة أن تندب النيابة العامة لمباشرة أي إجراء من إجراءات التحقيق الذي تأمر به.$ps1_2000_36$, '2020-09-05', 'active' FROM ins_ps1_2000_36_0;

WITH ins_ps1_2000_37_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 37, 0, NULL, NULL, $ps1_2000_37$للمحكمة ولللنيابة العامة أن تدعو من ترى فائدة من سماع أقواله في كل تحقيق تجريه، فإن تخلف عن الحضور بالجلسة المحددة أو امتنع عن الإدلاء بأقواله دون مبرر قانوني – جاز الحكم عليه بغرامة لا تجاوز مائة جنيه، فإن لم يحضر جاز للمحكمة وللنيابة العامة أن تأمر بإحضاره. وللمحكمة أن تقيل المحكوم عليه من الغرامة كلها أو بعضها إذا أبدى عذراً مقبولاً.$ps1_2000_37$
  FROM laws WHERE law_no = 1 AND law_year = 2000
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $ps1_2000_37$للمحكمة ولللنيابة العامة أن تدعو من ترى فائدة من سماع أقواله في كل تحقيق تجريه، فإن تخلف عن الحضور بالجلسة المحددة أو امتنع عن الإدلاء بأقواله دون مبرر قانوني – جاز الحكم عليه بغرامة لا تجاوز مائة جنيه، فإن لم يحضر جاز للمحكمة وللنيابة العامة أن تأمر بإحضاره. وللمحكمة أن تقيل المحكوم عليه من الغرامة كلها أو بعضها إذا أبدى عذراً مقبولاً.$ps1_2000_37$, '2020-09-05', 'active' FROM ins_ps1_2000_37_0;

WITH ins_ps1_2000_38_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 38, 0, NULL, NULL, $ps1_2000_38$إذا رأت النيابة العامة أن طلب توقيع الحجر أو سلب الولاية أو الحد منها أو وقفها أو إثبات الغيبة يقتضي اتخاذ إجراءات تحقيق تستغرق فترة من الزمن يخشى خلالها من ضياع حق أو مال، رفعت الأمر للمحكمة لتأذن باتخاذ ما تراه من إجراءات تحفظية أو لتأمر بمنع المقدم ضده الطلب من التصرف في الأموال كلها أو بعضها أو تقييد سلطته في إدارتها أو تعيين مدير مؤقت يتولى إدارة تلك الأموال.$ps1_2000_38$
  FROM laws WHERE law_no = 1 AND law_year = 2000
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $ps1_2000_38$إذا رأت النيابة العامة أن طلب توقيع الحجر أو سلب الولاية أو الحد منها أو وقفها أو إثبات الغيبة يقتضي اتخاذ إجراءات تحقيق تستغرق فترة من الزمن يخشى خلالها من ضياع حق أو مال، رفعت الأمر للمحكمة لتأذن باتخاذ ما تراه من إجراءات تحفظية أو لتأمر بمنع المقدم ضده الطلب من التصرف في الأموال كلها أو بعضها أو تقييد سلطته في إدارتها أو تعيين مدير مؤقت يتولى إدارة تلك الأموال.$ps1_2000_38$, '2020-09-05', 'active' FROM ins_ps1_2000_38_0;

WITH ins_ps1_2000_39_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 39, 0, NULL, NULL, $ps1_2000_39$على النيابة العامة أن تقدم للمحكمة مذكرة مسببة بمن ترشحه للنيابة عن عديم الأهلية أو ناقصها أو عن الغائب أو من ترشحه مساعدا قضائيا، وذلك خلال ثمانية أيام على الأكثر من تاريخ إبلاغها بالسبب الموجب لتعيينه. وتعين المحكمة النائب أو المساعد القضائي بعد أخذ رأي ذوي الشأن.$ps1_2000_39$
  FROM laws WHERE law_no = 1 AND law_year = 2000
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $ps1_2000_39$على النيابة العامة أن تقدم للمحكمة مذكرة مسببة بمن ترشحه للنيابة عن عديم الأهلية أو ناقصها أو عن الغائب أو من ترشحه مساعدا قضائيا، وذلك خلال ثمانية أيام على الأكثر من تاريخ إبلاغها بالسبب الموجب لتعيينه. وتعين المحكمة النائب أو المساعد القضائي بعد أخذ رأي ذوي الشأن.$ps1_2000_39$, '2020-09-05', 'active' FROM ins_ps1_2000_39_0;

WITH ins_ps1_2000_40_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 40, 0, NULL, NULL, $ps1_2000_40$تخطر النيابة العامة الوصي أو القيم أو الوكيل عن الغائب أو المساعد القضائي أو المدير المؤقت بالقرار الصادر بتعيينه إذا صدر في غيبته، وعلى من يرفض التعيين إبلاغ النيابة العامة كتابة برفضه خلال ثمانية أيام من تاريخ علمه بالقرار وإلا كان مسئولا عن المهام الموكلة إليه من تاريخ العلم. وفي حالة الرفض تعين المحكمة بدلاً منه على وجه السرعة.$ps1_2000_40$
  FROM laws WHERE law_no = 1 AND law_year = 2000
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $ps1_2000_40$تخطر النيابة العامة الوصي أو القيم أو الوكيل عن الغائب أو المساعد القضائي أو المدير المؤقت بالقرار الصادر بتعيينه إذا صدر في غيبته، وعلى من يرفض التعيين إبلاغ النيابة العامة كتابة برفضه خلال ثمانية أيام من تاريخ علمه بالقرار وإلا كان مسئولا عن المهام الموكلة إليه من تاريخ العلم. وفي حالة الرفض تعين المحكمة بدلاً منه على وجه السرعة.$ps1_2000_40$, '2020-09-05', 'active' FROM ins_ps1_2000_40_0;

WITH ins_ps1_2000_41_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 41, 0, NULL, NULL, $ps1_2000_41$تقوم النيابة العامة بعد صدور قرار المحكمة بتعيين النائب، بجرد أموال عديم الأهلية أو ناقصها أو الغائب بمحضر يحرر من نسختين.
ويتبع في الجرد الأحكام والإجراءات التي يصدر بها قرار من وزير العدل ويدعى لحضور الجرد جميع ذوي الشأن والقاصر الذي أتم خمس عشرة سنة ميلادية إذا رأت النيابة العامة ضرورة لحضوره.
وللنيابة العامة أن تستعين بأهل الخبرة في جرد الأموال وتقييمها وتقدير الديون وتسلم الأموال بعد انتهاء الجرد إلى النائب المعين من المحكمة.$ps1_2000_41$
  FROM laws WHERE law_no = 1 AND law_year = 2000
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $ps1_2000_41$تقوم النيابة العامة بعد صدور قرار المحكمة بتعيين النائب، بجرد أموال عديم الأهلية أو ناقصها أو الغائب بمحضر يحرر من نسختين.
ويتبع في الجرد الأحكام والإجراءات التي يصدر بها قرار من وزير العدل ويدعى لحضور الجرد جميع ذوي الشأن والقاصر الذي أتم خمس عشرة سنة ميلادية إذا رأت النيابة العامة ضرورة لحضوره.
وللنيابة العامة أن تستعين بأهل الخبرة في جرد الأموال وتقييمها وتقدير الديون وتسلم الأموال بعد انتهاء الجرد إلى النائب المعين من المحكمة.$ps1_2000_41$, '2020-09-05', 'active' FROM ins_ps1_2000_41_0;

WITH ins_ps1_2000_42_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 42, 0, NULL, NULL, $ps1_2000_42$ترفع النيابة العامة محضر الجرد إلى المحكمة للتصديق عليه بعد التحقق من صحة البيانات الواردة فيه.$ps1_2000_42$
  FROM laws WHERE law_no = 1 AND law_year = 2000
