SELECT id, 1, $ps1_2000_42$ترفع النيابة العامة محضر الجرد إلى المحكمة للتصديق عليه بعد التحقق من صحة البيانات الواردة فيه.$ps1_2000_42$, '2020-09-05', 'active' FROM ins_ps1_2000_42_0;

WITH ins_ps1_2000_43_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 43, 0, NULL, NULL, $ps1_2000_43$يجب على النيابة العامة عند عرض محضر الجرد على المحكمة للتصديق عليه أن ترفق مذكرة برأيها في المسائل الآتية بحسب الأحوال:
1 – الاستمرار في الملكية الشائعة أو الخروج منها وفي استغلال المحال التجارية والصناعية أو المكاتب المهنية أو تصفيتها ووسائل الوفاء بالديون والقرارات المنفذة لذلك.
2 – تقدير النفقة الدائمة اللازمة للقاصر أو المحجور عليه.
3 – اتخاذ الطرق المؤدية لحسن إدارة الأموال وصيانتها.
وتلتزم المحكمة بالتصديق على محضر الجرد وبالفصل في المسائل المشار إليها على وجه السرعة.$ps1_2000_43$
  FROM laws WHERE law_no = 1 AND law_year = 2000
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $ps1_2000_43$يجب على النيابة العامة عند عرض محضر الجرد على المحكمة للتصديق عليه أن ترفق مذكرة برأيها في المسائل الآتية بحسب الأحوال:
1 – الاستمرار في الملكية الشائعة أو الخروج منها وفي استغلال المحال التجارية والصناعية أو المكاتب المهنية أو تصفيتها ووسائل الوفاء بالديون والقرارات المنفذة لذلك.
2 – تقدير النفقة الدائمة اللازمة للقاصر أو المحجور عليه.
3 – اتخاذ الطرق المؤدية لحسن إدارة الأموال وصيانتها.
وتلتزم المحكمة بالتصديق على محضر الجرد وبالفصل في المسائل المشار إليها على وجه السرعة.$ps1_2000_43$, '2020-09-05', 'active' FROM ins_ps1_2000_43_0;

WITH ins_ps1_2000_44_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 44, 0, NULL, NULL, $ps1_2000_44$للمحكمة ولو من تلقاء نفسها أن تعدل عن أي قرار أصدرته في المسائل المبينة في المادة السابقة أو عن أي إجراء من الإجراءات التحفظية إذا تبينت ما يدعو لذلك.
ولا يمس عدول المحكمة عن قرار سبق أن أصدرته بحقوق الغير حسن النية الناشئة عن أي اتفاق.$ps1_2000_44$
  FROM laws WHERE law_no = 1 AND law_year = 2000
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $ps1_2000_44$للمحكمة ولو من تلقاء نفسها أن تعدل عن أي قرار أصدرته في المسائل المبينة في المادة السابقة أو عن أي إجراء من الإجراءات التحفظية إذا تبينت ما يدعو لذلك.
ولا يمس عدول المحكمة عن قرار سبق أن أصدرته بحقوق الغير حسن النية الناشئة عن أي اتفاق.$ps1_2000_44$, '2020-09-05', 'active' FROM ins_ps1_2000_44_0;

WITH ins_ps1_2000_45_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 45, 0, NULL, NULL, $ps1_2000_45$إذا عينت المحكمة مصفيا للتركة قبل التصديق على محضر الجرد يتولى المصفي جرد التركة كلها ويحرر محضرا تفصيليا بما لها وما عليها يوقعه هو وعضو النيابة العامة والنائب المعين ومن يكون حاضرا من الورثة الراشدين.
وإذا عين المصفى بعد التصديق على محضر الجرد يقوم النائب عن عديم الأهلية أو ناقصها أو عن الغائب بتسليم نصيب الأخير في التركة إلى المصفى بمحضر يوقعه هو والمصفى وعضو النيابة العامة ومن يكون حاضرا من الورثة الراشدين، وذلك ما لم ير المصفى إبقاء المال كله أو بعضه تحت يد النائب لحفظه وإدارته مؤقتا حتى تتم التصفية ويثبت ذلك على نسختي محضر الجرد ويوقع عليه الأشخاص السابق ذكرهم.
وبعد انتهاء التصفية يسلم ما يؤول من التركة إلى النائب عن عديم الأهلية أو ناقصها أو عن الغائب مع مراعاة الإجراءات المنصوص عليها في هذا القانون.$ps1_2000_45$
  FROM laws WHERE law_no = 1 AND law_year = 2000
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $ps1_2000_45$إذا عينت المحكمة مصفيا للتركة قبل التصديق على محضر الجرد يتولى المصفي جرد التركة كلها ويحرر محضرا تفصيليا بما لها وما عليها يوقعه هو وعضو النيابة العامة والنائب المعين ومن يكون حاضرا من الورثة الراشدين.
وإذا عين المصفى بعد التصديق على محضر الجرد يقوم النائب عن عديم الأهلية أو ناقصها أو عن الغائب بتسليم نصيب الأخير في التركة إلى المصفى بمحضر يوقعه هو والمصفى وعضو النيابة العامة ومن يكون حاضرا من الورثة الراشدين، وذلك ما لم ير المصفى إبقاء المال كله أو بعضه تحت يد النائب لحفظه وإدارته مؤقتا حتى تتم التصفية ويثبت ذلك على نسختي محضر الجرد ويوقع عليه الأشخاص السابق ذكرهم.
وبعد انتهاء التصفية يسلم ما يؤول من التركة إلى النائب عن عديم الأهلية أو ناقصها أو عن الغائب مع مراعاة الإجراءات المنصوص عليها في هذا القانون.$ps1_2000_45$, '2020-09-05', 'active' FROM ins_ps1_2000_45_0;

WITH ins_ps1_2000_46_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 46, 0, NULL, NULL, $ps1_2000_46$يجب على النائب عن عديم الأهلية أو ناقصها أو عن الغائب أو المدير المؤقت أن يودع قلم كتاب المحكمة حسابا عن إدارته مشفوعا بالمستندات التي تؤيده في الميعاد المحدد قانونا وكلما طلبت منه المحكمة ذلك في الميعاد الذي تحدده. فإذا انقضى الميعاد ولم يقدم الحساب جاز للمحكمة أن تحكم عليه بغرامة لا تزيد على خمسمائة جنيه فإن تكرر منه ذلك جاز أن تحكم عليه بغرامة لا تزيد على ألف جنيه، وذلك دون إخلال بالجزاءات الأخرى المنصوص عليها قانونا. وإذا قدم النائب الحساب وأبدى عذرا عن التأخير قبلته المحكمة، جاز لها أن تقبله من كل الغرامة أو بعضها. وعلى المحكمة أن تأمر مؤقتا بإيداع المبالغ التي لا ينازع مقدم الحساب في ثبوتها في ذمته، دون أن يعتبر ذلك مصادقة على الحساب. وتفصل المحكمة في صحة الحساب المقدم إليها ويجب أن يشمل القرار النهائي الذي تصدره المحكمة بشأن الحساب الأمر بإلزام مقدمه بأداء المبلغ المتبقي في ذمته وإيداعه خزانة المحكمة في ميعاد تحدده.$ps1_2000_46$
  FROM laws WHERE law_no = 1 AND law_year = 2000
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $ps1_2000_46$يجب على النائب عن عديم الأهلية أو ناقصها أو عن الغائب أو المدير المؤقت أن يودع قلم كتاب المحكمة حسابا عن إدارته مشفوعا بالمستندات التي تؤيده في الميعاد المحدد قانونا وكلما طلبت منه المحكمة ذلك في الميعاد الذي تحدده. فإذا انقضى الميعاد ولم يقدم الحساب جاز للمحكمة أن تحكم عليه بغرامة لا تزيد على خمسمائة جنيه فإن تكرر منه ذلك جاز أن تحكم عليه بغرامة لا تزيد على ألف جنيه، وذلك دون إخلال بالجزاءات الأخرى المنصوص عليها قانونا. وإذا قدم النائب الحساب وأبدى عذرا عن التأخير قبلته المحكمة، جاز لها أن تقبله من كل الغرامة أو بعضها. وعلى المحكمة أن تأمر مؤقتا بإيداع المبالغ التي لا ينازع مقدم الحساب في ثبوتها في ذمته، دون أن يعتبر ذلك مصادقة على الحساب. وتفصل المحكمة في صحة الحساب المقدم إليها ويجب أن يشمل القرار النهائي الذي تصدره المحكمة بشأن الحساب الأمر بإلزام مقدمه بأداء المبلغ المتبقي في ذمته وإيداعه خزانة المحكمة في ميعاد تحدده.$ps1_2000_46$, '2020-09-05', 'active' FROM ins_ps1_2000_46_0;

WITH ins_ps1_2000_47_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 47, 0, NULL, NULL, $ps1_2000_47$للنيابة العامة أن تصرح للنائب عن عديم الأهلية أو ناقصها أو عن الغائب بالصرف من الأموال السائلة لأي من هؤلاء دون الرجوع إلى المحكمة بما لا يجاوز مبلغ عشرة آلاف جنيه، ويجوز زيادته إلى عشرين ألف جنيه بقرار من المحامي العام المختص، وذلك لمرة واحدة كل ثلاثة أشهر. ويجوز بقرار مسبب من المحامي العام في حالة الضرورة القصوى كالحوادث، والحالات المرضية، والتي تستدعى تدخلاً طبيًا عاجلاً زيادة المبلغ المشار إليه في الفقرة الأولى من هذه المادة بقدر حالة الضرورة ونفقتها. ويلتزم النائب المصرح له بالصرف بتقديم المستندات المؤيدة للإنفاق في حالة الضرورة، قبل تقديم طلب الصرف التالي.$ps1_2000_47$
  FROM laws WHERE law_no = 1 AND law_year = 2000
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $ps1_2000_47$للنيابة العامة أن تصرح للنائب عن عديم الأهلية أو ناقصها أو عن الغائب بالصرف من الأموال السائلة لأي من هؤلاء دون الرجوع إلى المحكمة بما لا يجاوز مبلغ عشرة آلاف جنيه، ويجوز زيادته إلى عشرين ألف جنيه بقرار من المحامي العام المختص، وذلك لمرة واحدة كل ثلاثة أشهر. ويجوز بقرار مسبب من المحامي العام في حالة الضرورة القصوى كالحوادث، والحالات المرضية، والتي تستدعى تدخلاً طبيًا عاجلاً زيادة المبلغ المشار إليه في الفقرة الأولى من هذه المادة بقدر حالة الضرورة ونفقتها. ويلتزم النائب المصرح له بالصرف بتقديم المستندات المؤيدة للإنفاق في حالة الضرورة، قبل تقديم طلب الصرف التالي.$ps1_2000_47$, '2020-09-05', 'active' FROM ins_ps1_2000_47_0;

