  SELECT id, 53, 0, NULL, NULL, $ps1_2000_53$يجب على المحكمة أن تودع قلم الكتاب أسباب القرارات القطعية الصادرة في مواد الحجر والمساعدة القضائية والولاية والغيبة والحساب والإذن بالتصرف وعزل الوصي، والقرارات الصادرة وفقاً لحكم المادة (38) من هذا القانون، وذلك في ميعاد ثمانية أيام من تاريخ النطق بها إذا صدرت من محكمة جزئية وخمسة عشر يوماً إذا صدرت من غيرها. وفيما عدا ذلك من قرارات تصدر في مسائل الولاية على المال، يجوز للمحكمة تسبيب هذه القرارات أو الاكتفاء بالتوقيع على محضر الجلسة المشتمل على المنطوق.$ps1_2000_53$
  FROM laws WHERE law_no = 1 AND law_year = 2000
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id
)
