WITH ins_ps1_2000_54_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 54, 0, NULL, NULL, $ps1_2000_54$تكون القرارات الصادرة من محكمة أول درجة بصفة إبتدائية في مسائل الولاية على المال واجبة النفاذ ولو مع حصول استئنافها عدا تلك الصادرة في المسائل الآتية:
1 – الحساب.
2 – رفع الحجر وإنهاء المساعدة القضائية.
3 – رد الولاية.
4 – إعادة الإذن للقاصر أو المحجور عليه بالتصرف أو الإدارة.
5 – ثبوت الرشد بعد القرار باستمرار الوصاية أو الولاية.
6 – الإذن بالتصرف للنائب عن عديم الأهلية أو ناقصها أو عن الغائب.
وللمحكمة المنظور أمامها الاستئناف أن تأمر بوقف التنفيذ مؤقتا حتى يفصل في الطعن.$ps1_2000_54$
  FROM laws WHERE law_no = 1 AND law_year = 2000
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id
)
