  SELECT id, 58, 0, NULL, NULL, $ps1_2000_58$تنظر المحكمة الاستئنافية الدعوى بحالتها التي كانت عليها قبل صدور الحكم المستأنف بالنسبة لما رفع عنه الاستئناف فقط.
