WITH ins_ps1_2000_63_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 63, 0, NULL, NULL, $ps1_2000_63$لا تنفذ الأحكام الصادرة بفسخ عقود الزواج أو بطلانها أو بالطلاق أو التطليق إلا بانقضاء مواعيد الطعن عليها بطريق النقض، فإذا طعن عليها في الميعاد القانوني، استمر عدم تنفيذها إلى حين الفصل في الطعن. وعلى رئيس المحكمة أو من ينيبه تحديد جلسة لنظر الطعن مباشرة أمام المحكمة في موعد لا يجاوز ستين يوماً من تاريخ إيداع صحيفة الطعن قلم كتاب المحكمة أو وصولها إليه، وعلى النيابة العامة تقديم مذكرة برأيها خلال ثلاثين يوما على الأكثر قبل الجلسة المحددة لنظر الطعن. وإذا نقضت المحكمة الحكم كان عليها أن تفصل في الموضوع.$ps1_2000_63$
  FROM laws WHERE law_no = 1 AND law_year = 2000
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $ps1_2000_63$لا تنفذ الأحكام الصادرة بفسخ عقود الزواج أو بطلانها أو بالطلاق أو التطليق إلا بانقضاء مواعيد الطعن عليها بطريق النقض، فإذا طعن عليها في الميعاد القانوني، استمر عدم تنفيذها إلى حين الفصل في الطعن. وعلى رئيس المحكمة أو من ينيبه تحديد جلسة لنظر الطعن مباشرة أمام المحكمة في موعد لا يجاوز ستين يوماً من تاريخ إيداع صحيفة الطعن قلم كتاب المحكمة أو وصولها إليه، وعلى النيابة العامة تقديم مذكرة برأيها خلال ثلاثين يوما على الأكثر قبل الجلسة المحددة لنظر الطعن. وإذا نقضت المحكمة الحكم كان عليها أن تفصل في الموضوع.$ps1_2000_63$, '2020-09-05', 'active' FROM ins_ps1_2000_63_0;

WITH ins_ps1_2000_64_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 64, 0, NULL, NULL, $ps1_2000_64$لا يجوز التماس إعادة النظر في مسائل الولاية على المال إلا في القرارات الانتهائية الصادرة في المواد الآتية:
1 – توقيع الحجر أو تقرير المساعدة القضائية أو إثبات الغيبة.
2 – تثبيت الوصي المختار أو الوكيل عن الغائب.
3 – عزل الوصي والقيم والوكيل أو الحد من سلطته.
4 – سلب الولاية أو وقفها أو الحد منها.
5 – استمرار الولاية أو الوصاية على القاصر.
6 – الفصل في الحساب.$ps1_2000_64$
  FROM laws WHERE law_no = 1 AND law_year = 2000
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id
)
