WITH ins_ps1_2000_70_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 70, 0, NULL, NULL, $ps1_2000_70$يجوز للنيابة العامة، متى عرضت عليها منازعة بشأن حضانة صغير في سن حضانة النساء، أو طلبت حضانته مؤقتاً من يرجح الحكم لها بذلك، أن تصدر بعد إجراء التحقيق المناسب قرارا مسببا بتسليم الصغير إلى من تتحقق مصلحته معها.
ويصدر القرار من رئيس نيابة على الأقل، ويكون واجب التنفيذ فوراً إلى حين صدور حكم من المحكمة المختصة في موضوع حضانة الصغير.$ps1_2000_70$
  FROM laws WHERE law_no = 1 AND law_year = 2000
