WITH ins_ps1_2000_71_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 71, 0, NULL, NULL, $ps1_2000_71$ينشأ نظام لتأمين الأسرة، من بين أهدافه ضمان تنفيذ الأحكام الصادرة بتقرير نفقة للزوجة أو المطلقة أو الأولاد أو الأقارب، يتولى الإشراف على تنفيذه بنك ناصر الاجتماعي.
