WITH ins_ps1_2000_73_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 73, 0, NULL, NULL, $ps1_2000_73$على الوزارات والمصالح الحكومية ووحدات الإدارة المحلية والهيئات العامة ووحدات القطاع العامة وقطاع الأعمال العام وجهات القطاع الخاص والهيئة القومية للتأمين الاجتماعي وإدارة التأمين والمعاشات للقوات المسلحة والنقابات المهنية وغيرها من جهات أخرى، بناء على طلب من بنك ناصر الاجتماعي مرفق به صورة طبق الأصل من الصورة التنفيذية للحكم وما يفيد تمام الإعلان أن تقوم بخصم المبالغ في الحدود التي يجوز الحجز عليها وفقاً للمادة (76) من هذا القانون من المرتبات وما في حكمها والمعاشات وإيداعها خزانة البنك فور وصول الطلب إليها ودون حاجة إلى إجراء آخر.$ps1_2000_73$
  FROM laws WHERE law_no = 1 AND law_year = 2000
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
