  SELECT id, 74, 0, NULL, NULL, $ps1_2000_74$إذا كان المحكوم عليه من غير ذوي المرتبات أو الأجور أو المعاشات وما في حكمها، وجب عليه أن يودع المبلغ المحكوم به خزانة بنك ناصر الاجتماعي أو أحد فروعه أو وحدة الشئون الاجتماعية الذي يقع محل إقامته في دائرة أي منها في الأسبوع الأول من كل شهر متى قام البنك بالتنبيه عليه بالوفاء.$ps1_2000_74$
