WITH ins_ps1_2000_76_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 76, 0, NULL, NULL, $ps1_2000_76$استثناء مما تقرره القوانين في شأن قواعد الحجز على المرتبات أو الأجور أو المعاشات وما في حكمها، يكون الحد الأقصى لما يجوز الحجز عليه منها وفاء لدين نفقة أو أجر أو ما في حكمها للزوجة أو المطلقة أو الأولاد أو الوالدين، في حدود النسب الآتية:
( أ ) 25% للزوجة أو المطلقة، وتكون 40% في حالة وجود أكثر من واحدة.
(ب) 25% للوالدين أو أيهما.
(ج) 35% للولدين أو أقل.
(د) 40% للزوجة أو المطلقة ولولد أو اثنين والوالدين أو أيهما.
(هـ) 50% للزوجة أو المطلقة وأكثر من ولدين والوالدين أو أيهما.
وفي جميع الأحوال لا يجوز أن تزيد النسبة التي يجوز الحجز عليها على (50%) تقسم بين المستحقين بنسبة ما حكم به لكل منهم.

المادة (76 مكررا)
إذا امتنع المحكوم عليه عن تنفيذ الحكم النهائي الصادر في دعاوى النفقات والأجور وما في حكمها جاز للمحكوم له أن يرفع الأمر إلى المحكمة التي أصدرت الحكم أو التي يجرى التنفيذ بدائرتها، ومتى ثبت لديها إن المحكوم عليه قادر على القيام بأداء ما حكم به وأمرته بالأداء ولم يمتثل حكمت بحبسه مدة لا تزيد على ثلاثين يوماً.
فإذا أدى المحكوم عليه ما حكم به أو أحضر كفيلا يقبله الصادر لصالحه الحكم فإنه يخلى سبيله، وذلك كله دون إخلال بحق المحكوم له فى التنفيذ بالطرق العادية.
ولا يجوز فى الأحوال التى تطبق فيها هذه المادة السير فى الإجراءات المنصوص عليها فى المادة (293) من قانون العقوبات ما لم يكن المحكوم له قد استنفذ الإجراءات المشار إليها فى الفقرة الأولى.
وإذا نفذ بالإكراه البدني على شخص وفقاً لحكم هذه المادة، ثم حكمت عليه بسبب الواقعة ذاتها بعقوبة الحبس طبقاً للمادة (293) من قانون العقوبات، استنزلت مدة الإكراه البدنى الأولى من مدة الحبس المحكوم بها، فإذا حكم عليه بغرامة خفضت عند التنفيذ بمقدار خمسة جنيهات عن كل يوم من أيام الإكراه البدنى الذى سبق إنفاذه عليه.$ps1_2000_76$
  FROM laws WHERE law_no = 1 AND law_year = 2000
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $ps1_2000_76$استثناء مما تقرره القوانين في شأن قواعد الحجز على المرتبات أو الأجور أو المعاشات وما في حكمها، يكون الحد الأقصى لما يجوز الحجز عليه منها وفاء لدين نفقة أو أجر أو ما في حكمها للزوجة أو المطلقة أو الأولاد أو الوالدين، في حدود النسب الآتية:
( أ ) 25% للزوجة أو المطلقة، وتكون 40% في حالة وجود أكثر من واحدة.
(ب) 25% للوالدين أو أيهما.
(ج) 35% للولدين أو أقل.
(د) 40% للزوجة أو المطلقة ولولد أو اثنين والوالدين أو أيهما.
(هـ) 50% للزوجة أو المطلقة وأكثر من ولدين والوالدين أو أيهما.
وفي جميع الأحوال لا يجوز أن تزيد النسبة التي يجوز الحجز عليها على (50%) تقسم بين المستحقين بنسبة ما حكم به لكل منهم.

المادة (76 مكررا)
