2 – البحث والتفتيش والدخول والنفاذ إلى برامج الحاسب وقواعد البيانات وغيرها من الأجهزة والنظم المعلوماتية تحقيقًا لغرض الضبط.

3 – أن تأمر مقدم الخدمة بتسليم ما لدية من بيانات أو معلومات تتعلق بنظام معلوماتي أو جهاز تقني، موجودة تحت سيطرته أو مخزنة لديه، وكذا بيانات مستخدمي خدمته وحركة الاتصالات التي تمت على ذلك النظام أو الجهاز التقني.

وفي كل الأحوال، يجب أن يكون أمر جهة التحقيق المختصة مسببًا. ويكون استئناف الأوامر المتقدمة أمام المحكمة الجنائية المختصة منعقدة في غرفة المشورة في المواعيد، ووفقًا للإجراءات المقررة بقانون الإجراءات الجنائية.$cyber175_6$, '2018-08-14', 'active' FROM ins_cyber175_6_0;

WITH ins_cyber175_7_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 7, 0, NULL, NULL, $cyber175_7$لجهة التحقيق المختصة، متى قامت أدلة على قيام موقع يُبث داخل الدولة أو خارجها، بوضع أي عبارات أو أرقام أو صور أو أفلام أو أي مواد دعائية، أو ما في حكمها بما يُعد جريمة من الجرائم المنصوص عليها بالقانون، وتشكل تهديدًا للأمن القومي أو تعرض أمن البلاد أو اقتصادها القومي للخطر، أن تأمر بحجب الموقع أو المواقع محل البث، كلما أمكن تحقيق ذلك فنيًا.

وعلى جهة التحقيق عرض أمر الحجب على المحكمة المختصة منعقدة في غرفة المشورة، خلال أربع وعشرين ساعة مشفوعًا بمذكرة برأيها. وتُصدر المحكمة قرارها في الأمر مسببًا إما بالقبول أو بالرفض، في مدة لا تجاوز اثنتين وسبعين ساعة من وقت عرضه عليها.

ويجوز في حالة الاستعجال لوجود خطر حال أو ضرر وشيك الوقوع، أن تقوم جهات التحري والضبط المختصة بإبلاغ الجهاز، ليقوم بإخطار مقدم الخدمة على الفور بالحجب المؤقت للموقع أو المحتوى أو المواقع أو الروابط المذكورة في الفقرة الأولى من هذه المادة وفقًا لأحكامها. ويلتزم مقدم الخدمة بتنفيذ مضمون الإخطار فور وروده إليه.

وعلى جهة التحري والضبط التي قامت بالإبلاغ أن تحرر محضرًا تثبت فيه ما تم من إجراءات وفق أحكام الفقرة السابقة يُعرض على جهات التحقيق خلال ثمانٍ وأربعين ساعة من تاريخ الإبلاغ الذي وجهته للجهاز، وتتبع في هذا المحضر ذات الإجراءات المبينة بالفقرة الثانية من هذه المادة، وتصدر المحكمة المختصة قرارها في هذه الحالة، أما بتأييد ما تم من إجراءات حجب أو بوقفها.

فإذا لم يُعرض المحضر المشار إليه في الفقرة السابقة في الموعد المحدد، يعد الحجب الذي تم كأن لم يكن.

ولمحكمة الموضوع أثناء نظر الدعوى أو بناءً على طلب جهة التحقيق أو الجهاز أو ذوي الشأن أن تأمر بإنهاء القرار الصادر بالحجب أو تعديل نطاقه.

وفي جميع الأحوال، يسقط القرار الصادر بالحجب بصدور أمر بألا وجه لإقامة الدعوى الجنائية، أو بصدور حكم نهائي فيها بالبراءة.$cyber175_7$
  FROM laws WHERE law_no = 175 AND law_year = 2018
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cyber175_7$لجهة التحقيق المختصة، متى قامت أدلة على قيام موقع يُبث داخل الدولة أو خارجها، بوضع أي عبارات أو أرقام أو صور أو أفلام أو أي مواد دعائية، أو ما في حكمها بما يُعد جريمة من الجرائم المنصوص عليها بالقانون، وتشكل تهديدًا للأمن القومي أو تعرض أمن البلاد أو اقتصادها القومي للخطر، أن تأمر بحجب الموقع أو المواقع محل البث، كلما أمكن تحقيق ذلك فنيًا.

