WITH ins_cyber175_8_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 8, 0, NULL, NULL, $cyber175_8$لكل من صدر ضده أمر قضائي من المنصوص عليه بالمادة (7) من هذا القانون، وللنيابة العامة ولجة التحقيق المختصة ولكل ذوي شأن، أن يتظلم منه، أو من إجراءات تنفيذه، أمام محكمة الجنايات المختصة بعد انقضاء سبعة أيام من تاريخ صدور الأمر أو من تاريخ تنفيذه بحسب الأحوال، فإذا رُفض تظلمه فله أن يتقدم بتظلم جديد كلما انقضت ثلاثة أشهر من تاريخ الحكم برفض التظلم. وفي جميع الأحوال، يكون التظلم بتقرير يودع قلم كتاب محكمة الجنايات المختصة، وعلى رئيس المحكمة أن يحدد جلسة لنظر التظلم يعلن بها المتظلم والجهاز وكل ذي شأن، وعلى المحكمة أن تفصل في التظلم خلال مدة لا تجاوز سبعة أيام من تاريخ التقرير به.$cyber175_8$
  FROM laws WHERE law_no = 175 AND law_year = 2018
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cyber175_8$لكل من صدر ضده أمر قضائي من المنصوص عليه بالمادة (7) من هذا القانون، وللنيابة العامة ولجة التحقيق المختصة ولكل ذوي شأن، أن يتظلم منه، أو من إجراءات تنفيذه، أمام محكمة الجنايات المختصة بعد انقضاء سبعة أيام من تاريخ صدور الأمر أو من تاريخ تنفيذه بحسب الأحوال، فإذا رُفض تظلمه فله أن يتقدم بتظلم جديد كلما انقضت ثلاثة أشهر من تاريخ الحكم برفض التظلم. وفي جميع الأحوال، يكون التظلم بتقرير يودع قلم كتاب محكمة الجنايات المختصة، وعلى رئيس المحكمة أن يحدد جلسة لنظر التظلم يعلن بها المتظلم والجهاز وكل ذي شأن، وعلى المحكمة أن تفصل في التظلم خلال مدة لا تجاوز سبعة أيام من تاريخ التقرير به.$cyber175_8$, '2018-08-14', 'active' FROM ins_cyber175_8_0;

WITH ins_cyber175_9_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 9, 0, NULL, NULL, $cyber175_9$يجوز للنائب العام أو من يفوضه من المحاميين العامين الأول بنيابات الاستئناف، ولجهات التحقيق المختصة، عند الضرورة، أو عند وجود أدلة كافية على جدية الاتهام في ارتكاب جريمة من الجرائم المنصوص عليها في هذا القانون أو الشروع في ارتكابها، أن يأمر بمنع المتهم من السفر خارج البلاد أو بوضع اسمه على قوائم ترقب الوصول، بأمر مسبب لمدة محددة. ولمن صدر ضده أمر المنع من السفر أن يتظلم من هذا الأمر أمام محكمة الجنايات المختصة خلال خمسة عشر يومًا من تاريخ علمه به، فإذا رُفض تظلمه فله أن يتقدم بتظلم جديد كلما انقضت ثلاثة أشهر من تاريخ الحكم برفض التظلم. ويكون التظلم بتقرير يودع قلم كتاب محكمة الجنايات المختصة، وعلى رئيس المحكمة أن يحدد جلسة لنظر التظلم تُعلن بها النيابة العامة والمتظلم، وعلى المحكمة أن تفصل في التظلم خلال مدة لا تجاوز خمسة عشر يومًا من تاريخ التقرير به، بحكم مُسبب بعد سماع أقوال المتظلم والنيابة العامة أو جهة التحقيق المختصة حسب الأحوال، ولها في سبيل ذلك أن تتخذ ما تراه من إجراءات أو تحقيقات ترى لزومها في هذا الشأن. ويجوز للنيابة العامة وجهات التحقيق المختصة في كل وقت العدول عن الأمر الصادر منها، كما يجوز لها التعديل فيه برفع الاسم من قوائم المنع من السفر أو ترقب الوصول لمدة محددة، إذا دعت الضرورة لذلك. وفي جميع الأحوال، ينتهي المنع من السفر بمرور سنه من تاريخ صدور الأمر، أو بصدور قرار بألا وجه لإقامة الدعوى الجنائية، أو بصدور قرار نهائي فيها بالبراءة، أيهما أقرب.$cyber175_9$
  FROM laws WHERE law_no = 175 AND law_year = 2018
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cyber175_9$يجوز للنائب العام أو من يفوضه من المحاميين العامين الأول بنيابات الاستئناف، ولجهات التحقيق المختصة، عند الضرورة، أو عند وجود أدلة كافية على جدية الاتهام في ارتكاب جريمة من الجرائم المنصوص عليها في هذا القانون أو الشروع في ارتكابها، أن يأمر بمنع المتهم من السفر خارج البلاد أو بوضع اسمه على قوائم ترقب الوصول، بأمر مسبب لمدة محددة. ولمن صدر ضده أمر المنع من السفر أن يتظلم من هذا الأمر أمام محكمة الجنايات المختصة خلال خمسة عشر يومًا من تاريخ علمه به، فإذا رُفض تظلمه فله أن يتقدم بتظلم جديد كلما انقضت ثلاثة أشهر من تاريخ الحكم برفض التظلم. ويكون التظلم بتقرير يودع قلم كتاب محكمة الجنايات المختصة، وعلى رئيس المحكمة أن يحدد جلسة لنظر التظلم تُعلن بها النيابة العامة والمتظلم، وعلى المحكمة أن تفصل في التظلم خلال مدة لا تجاوز خمسة عشر يومًا من تاريخ التقرير به، بحكم مُسبب بعد سماع أقوال المتظلم والنيابة العامة أو جهة التحقيق المختصة حسب الأحوال، ولها في سبيل ذلك أن تتخذ ما تراه من إجراءات أو تحقيقات ترى لزومها في هذا الشأن. ويجوز للنيابة العامة وجهات التحقيق المختصة في كل وقت العدول عن الأمر الصادر منها، كما يجوز لها التعديل فيه برفع الاسم من قوائم المنع من السفر أو ترقب الوصول لمدة محددة، إذا دعت الضرورة لذلك. وفي جميع الأحوال، ينتهي المنع من السفر بمرور سنه من تاريخ صدور الأمر، أو بصدور قرار بألا وجه لإقامة الدعوى الجنائية، أو بصدور قرار نهائي فيها بالبراءة، أيهما أقرب.$cyber175_9$, '2018-08-14', 'active' FROM ins_cyber175_9_0;

WITH ins_cyber175_10_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 10, 0, NULL, NULL, $cyber175_10$يُنشأ بالجهاز سجلان لقيد الخبراء، يُقيد بأولهما الفنيون والتقنيون العاملون بالجهاز، ويقيد بالآخر الخبراء من الفنيين والتقنيين من غير العاملين به. وتُطبق على الخبراء في ممارسة عملهم وتحديد التزاماتهم وحقوقهم القواعد والأحكام الخاصة بقواعد تنظيم الخبرة أمام جهات القضاء. واستثناء من تلك القواعد، تسري على الخبراء المقيدين بالسجل الثاني القواعد والأحكام الخاصة بالمساءلة الإدارية والتأديبية الواردة بالقانون المنظم لعملهم إن وُجد. وتحدد اللائحة التنفيذية لهذا القانون قواعد وشروط وإجراءات القيد في كل من السجلين.
[ملاحظة تحرير: كلمة "القواعس" في المصدر مصححة هنا إلى "القواعد" - يُرجّح أنه خطأ مطبعي/OCR في الموقع المصدر ذاته]$cyber175_10$
  FROM laws WHERE law_no = 175 AND law_year = 2018
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cyber175_10$يُنشأ بالجهاز سجلان لقيد الخبراء، يُقيد بأولهما الفنيون والتقنيون العاملون بالجهاز، ويقيد بالآخر الخبراء من الفنيين والتقنيين من غير العاملين به. وتُطبق على الخبراء في ممارسة عملهم وتحديد التزاماتهم وحقوقهم القواعد والأحكام الخاصة بقواعد تنظيم الخبرة أمام جهات القضاء. واستثناء من تلك القواعد، تسري على الخبراء المقيدين بالسجل الثاني القواعد والأحكام الخاصة بالمساءلة الإدارية والتأديبية الواردة بالقانون المنظم لعملهم إن وُجد. وتحدد اللائحة التنفيذية لهذا القانون قواعد وشروط وإجراءات القيد في كل من السجلين.
[ملاحظة تحرير: كلمة "القواعس" في المصدر مصححة هنا إلى "القواعد" - يُرجّح أنه خطأ مطبعي/OCR في الموقع المصدر ذاته]$cyber175_10$, '2018-08-14', 'active' FROM ins_cyber175_10_0;

WITH ins_cyber175_11_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 11, 0, NULL, NULL, $cyber175_11$يكون للأدلة المستمدة أو المستخرجة من الأجهزة أو المعدات أو الوسائط الدعامات الإلكترونية، أو النظام المعلوماتي أو من برامج الحاسب، أو من أي وسيلة لتقنية المعلومات ذات قيمة وحجية الأدلة الجنائية المادية في الإثبات الجنائي متى توافرت بها الشروط الفنية الواردة باللائحة التنفيذية لهذا القانون.

