-- ===== fam10: قانون إنشاء محاكم الأسرة 10/2004 (15 مادة) =====

DO $dofam10$
DECLARE
  v_law_id uuid;
  v_article_count int;
BEGIN
  SELECT id INTO v_law_id FROM laws WHERE law_no = 10 AND law_year = 2004;
  IF v_law_id IS NULL THEN
    RAISE NOTICE 'law 10/2004 not found, skipping fix';
    RETURN;
  END IF;
  SELECT count(*) INTO v_article_count FROM articles WHERE law_id = v_law_id;
  IF v_article_count = 1 THEN
    DELETE FROM articles WHERE law_id = v_law_id AND article_no = 1 AND article_suffix_order = 0;
    RAISE NOTICE 'law 10/2004: removed legacy single-blob article row';
  ELSE
    RAISE NOTICE 'law 10/2004: already has % articles, skipping delete (already fixed or unexpected state)', v_article_count;
  END IF;
END
$dofam10$;

