SELECT id, 1, $fam10_10$تعقد جلسات محاكم الأسرة والدوائر الاستئنافية فى أماكن منفصلة عن أماكن انعقاد جلسات المحاكم الأخرى، وتزود بما يلزم من الوسائل التى تتناسب مع طبيعة المنازعات وأطرافها وما قد تقتضيه من حضور الصغار تلك الجلسات للاستماع إلى أقوالهم. وتسترشد المحكمة فى أحكامها وقراراتها بما تقتضيه مصالح الطفل الفضلى.$fam10_10$, '2017-12-25', 'active' FROM ins_fam10_10_0;

WITH ins_fam10_11_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 11, 0, NULL, NULL, $fam10_11$يكون حضور الخبيرين المنصوص عليهما فى المادة (2) من هذا القانون جلسات محكمة الأسرة وجوبيًا فى دعاوى الطلاق والتطليق والتفريق الجسمانى والفسخ وبطلان الزواج وحضانة الصغير ومسكن حضانته وحفظه ورؤيته وضمه والانتقال به وكذلك فى دعاوى النسب والطاعة. وللمحكمة أن تستعين بهما فى غير ذلك من مسائل الأحوال الشخصية إذا رأت ضرورة لذلك. وعلى كل منهما أن يقدم للمحكمة تقريرًا فى مجال تخصصه.$fam10_11$
  FROM laws WHERE law_no = 10 AND law_year = 2004
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id
)
