WITH ins_fam10_12_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 12, 0, NULL, NULL, $fam10_12$تكون محكمة الأسرة المختصة محليًا بنظر أول دعوى ترفع إليها من أحد الزوجين مختصة محليًا، دون غيرها، بنظر جميع الدعاوى التى ترفع بعد ذلك من أيهما، أو تكون متعلقة أو مترتبة على الزواج أو الطلاق أو التطليق أو التفريق الجسمانى أو الفسخ، وكذلك دعاوى النفقات أو الأجور وما فى حكمها سواءً للزوجة أو الأولاد أو الأقارب، ودعاوى الحبس لامتناع المحكوم عليه عن تنفيذ الأحكام الصادرة بها، وحضانة الصغير وحفظه ورؤيته وضمه والانتقال به ومسكن حضانته، وجميع دعاوى الأحوال الشخصية.$fam10_12$
  FROM laws WHERE law_no = 10 AND law_year = 2004
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id
)
