WITH ins_fam10_15_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 15, 0, NULL, NULL, $fam10_15$تنشأ بكل محكمة أسرة إدارة خاصة لتنفيذ الأحكام والقرارات الصادرة منها أو من دوائرها الاستئنافية، تزود بعدد كاف من محضرى التنفيذ المؤهلين المدربين الذين يصدر بتحديدهم قرار من رئيس المحكمة. ويتولى الإشراف على هذه الإدارة قاض للتنفيذ تختاره الجمعية العمومية للمحكمة الابتدائية من بين قضاة محكمة الأسرة فى دائرة تلك المحكمة.$fam10_15$
  FROM laws WHERE law_no = 10 AND law_year = 2004
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id
)
